package com.ridelink.drivervehicle.service;
import com.ridelink.drivervehicle.domain.*; import com.ridelink.drivervehicle.dto.DriverDtos.*; import com.ridelink.drivervehicle.exception.ApiException; import com.ridelink.drivervehicle.repository.DriverRepository; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class DriverService { private final DriverRepository drivers; public DriverService(DriverRepository d){drivers=d;} public DriverResponse create(ProfileRequest r){if(drivers.existsByUserId(r.userId())||drivers.existsByLicenseNumber(r.licenseNumber())||drivers.existsByVehiclePlateNumber(r.vehicle().plateNumber()))throw new ApiException(HttpStatus.CONFLICT,"Driver, license, or vehicle already exists");Driver d=new Driver();d.setId(UUID.randomUUID().toString());d.setUserId(r.userId());d.setLicenseNumber(r.licenseNumber());d.setServiceZone(r.serviceZone());d.setAvailability(Availability.OFFLINE);d.setCreatedAt(Instant.now());d.setVehicle(vehicle(r.vehicle()));return response(drivers.save(d));} public DriverResponse availability(String id,AvailabilityRequest r){Driver d=require(id);d.setAvailability(r.availability());return response(drivers.save(d));} public DriverResponse location(String id,LocationRequest r){Driver d=require(id);d.setLatitude(r.latitude());d.setLongitude(r.longitude());d.setServiceZone(r.zone());return response(drivers.save(d));} public List<DriverResponse> available(String zone){return drivers.findByAvailabilityAndServiceZone(Availability.ONLINE,zone).stream().map(this::response).toList();} private Driver require(String id){return drivers.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Driver not found"));} private Vehicle vehicle(VehicleRequest r){Vehicle v=new Vehicle();v.setMake(r.make());v.setModel(r.model());v.setPlateNumber(r.plateNumber());v.setCapacity(r.capacity());return v;} private DriverResponse response(Driver d){Vehicle v=d.getVehicle();return new DriverResponse(d.getId(),d.getUserId(),d.getLicenseNumber(),d.getAvailability(),d.getServiceZone(),d.getLatitude(),d.getLongitude(),new VehicleResponse(v.getMake(),v.getModel(),v.getPlateNumber(),v.getCapacity()),d.getCreatedAt());} }
